'use client'
import { createMachine, useId, useMachine, useSignalEffect, useSignals } from '@cascivo/core'
import { cloneElement, useRef } from 'react'
import type {
  CSSProperties,
  FocusEvent,
  HTMLAttributes,
  MouseEvent,
  ReactElement,
  ReactNode,
} from 'react'
import styles from './tooltip.module.css'

const machine = createMachine({
  initial: 'hidden' as const,
  states: {
    hidden: { on: { SHOW: 'visible' } },
    visible: { on: { HIDE: 'hidden' } },
  },
})

export interface TooltipProps {
  content: ReactNode
  /**
   * Side of the trigger the tip opens on: `top`, `right`, `bottom` or `left`.
   *
   * @defaultValue `top`
   * @see the component manifest
   */
  placement?: 'top' | 'right' | 'bottom' | 'left'
  children: ReactElement
  /**
   * Milliseconds to wait before showing
   *
   * @defaultValue `200`
   * @see the component manifest
   */
  delay?: number
}

export function Tooltip({ content, placement = 'top', children, delay = 200 }: TooltipProps) {
  useSignals()
  const [state, send] = useMachine(machine)
  // Stable, colon-stripped ids: SSR-safe and valid inside the CSS anchor-name.
  const tooltipId = useId('cascivo-tooltip')
  const anchorId = useId('cascivo-anchor')
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const floatingRef = useRef<HTMLSpanElement>(null)

  const isVisible = state.value === 'visible'

  const show = () => {
    clearTimeout(timer.current)
    timer.current = setTimeout(() => send('SHOW'), delay)
  }
  const hide = () => {
    clearTimeout(timer.current)
    send('HIDE')
  }

  useSignalEffect(() => () => clearTimeout(timer.current))

  useSignalEffect(() => {
    if (state.value === 'visible') {
      floatingRef.current?.showPopover()
    } else {
      floatingRef.current?.hidePopover()
    }
  })

  const trigger = children as ReactElement<HTMLAttributes<HTMLElement>>
  const triggerProps = trigger.props

  const merged: HTMLAttributes<HTMLElement> = {
    id: anchorId,
    style: { anchorName: `--tooltip-${anchorId}` } as CSSProperties,
    onMouseEnter: (event: MouseEvent<HTMLElement>) => {
      triggerProps.onMouseEnter?.(event)
      show()
    },
    onMouseLeave: (event: MouseEvent<HTMLElement>) => {
      triggerProps.onMouseLeave?.(event)
      hide()
    },
    onFocus: (event: FocusEvent<HTMLElement>) => {
      triggerProps.onFocus?.(event)
      show()
    },
    onBlur: (event: FocusEvent<HTMLElement>) => {
      triggerProps.onBlur?.(event)
      hide()
    },
    'aria-describedby': isVisible ? tooltipId : triggerProps['aria-describedby'],
  }

  return (
    <span className={styles['root']}>
      {cloneElement(trigger, merged)}
      <span
        ref={floatingRef}
        popover="manual"
        role="tooltip"
        id={tooltipId}
        data-placement={placement}
        data-state={isVisible ? 'visible' : 'hidden'}
        data-anchor={`--tooltip-${anchorId}`}
        className={styles['tooltip']}
      >
        {content}
      </span>
    </span>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    display: inline-flex;
  }

  .tooltip {
    position: absolute;
    z-index: var(--cascivo-z-tooltip);
    inline-size: max-content;
    max-inline-size: 16rem;
    padding-inline: var(--cascivo-space-3);
    padding-block: var(--cascivo-space-1);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-xs);
    line-height: var(--cascivo-leading-snug);
    color: var(--cascivo-color-text-on-accent);
    background-color: var(--cascivo-color-text);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-md);
    pointer-events: none;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--cascivo-motion-enter),
      visibility var(--cascivo-motion-enter);

    /* Reset default popover styles */
    &:popover-open {
      opacity: 1;
      visibility: visible;
    }

    &[data-state='visible'] {
      opacity: 1;
      visibility: visible;
    }

    @starting-style {
      &[data-state='visible'] {
        opacity: 0;
      }
    }

    &[data-placement='top'] {
      inset-block-end: calc(100% + var(--cascivo-space-2));
      inset-inline-start: 50%;
      translate: -50% 0;
    }
    &[data-placement='bottom'] {
      inset-block-start: calc(100% + var(--cascivo-space-2));
      inset-inline-start: 50%;
      translate: -50% 0;
    }
    &[data-placement='left'] {
      inset-inline-end: calc(100% + var(--cascivo-space-2));
      inset-block-start: 50%;
      translate: 0 -50%;
    }
    &[data-placement='right'] {
      inset-inline-start: calc(100% + var(--cascivo-space-2));
      inset-block-start: 50%;
      translate: 0 -50%;
    }
  }

  @supports (anchor-name: --a) and (position-anchor: --a) {
    .tooltip {
      position: fixed;
      inset: auto;
      position-anchor: var(--cascivo-tooltip-anchor, attr(data-anchor));
      margin: var(--cascivo-space-2);
      /* An anchored element lives in the top layer, so it is not clipped by the scroller its
         trigger sits in: scroll the trigger out of a panel and the tip stays painted over
         unrelated content, pointing at nothing. `anchors-visible` ties its visibility to the
         anchor's. Ignored where unsupported, which is the behaviour today. */
      position-visibility: anchors-visible;
    }

    .tooltip[data-placement='top'] {
      position-area: block-start span-inline-start;
      translate: 0 0;
    }

    .tooltip[data-placement='bottom'] {
      position-area: block-end span-inline-start;
      translate: 0 0;
    }

    .tooltip[data-placement='left'] {
      position-area: inline-start span-block-start;
      translate: 0 0;
    }

    .tooltip[data-placement='right'] {
      position-area: inline-end span-block-start;
      translate: 0 0;
    }

    @media (prefers-reduced-motion: no-preference) {
      .tooltip {
        transition:
          opacity var(--cascivo-motion-enter),
          visibility var(--cascivo-motion-enter),
          display var(--cascivo-motion-enter) allow-discrete,
          overlay var(--cascivo-motion-enter) allow-discrete;
      }

      @starting-style {
        .tooltip[data-state='visible'] {
          opacity: 0;
        }
      }
    }
  }
}

@media (forced-colors: active) {
  .tooltip {
    border: 1px solid CanvasText;
    background-color: Canvas;
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Tooltip',
  description: 'Contextual label shown on hover or focus',
  category: 'overlay',
  clientJs: 'required',
  states: ['hidden', 'visible'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'content',
      description: 'The tooltip content shown on hover/focus.',
      type: 'ReactNode',
      required: true,
    },
    {
      name: 'placement',
      description: 'Side of the trigger the tip opens on: `top`, `right`, `bottom` or `left`.',
      type: "'top' | 'right' | 'bottom' | 'left'",
      required: false,
      default: 'top',
    },
    {
      name: 'children',
      description: 'Content rendered inside the component.',
      type: 'ReactElement',
      required: true,
    },
    {
      name: 'delay',
      type: 'number',
      required: false,
      default: '200',
      description: 'Milliseconds to wait before showing',
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-on-accent',
    '--cascivo-radius-sm',
    '--cascivo-z-tooltip',
  ],
  accessibility: {
    role: 'tooltip',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Escape'],
    apgPattern: 'tooltip',
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    {
      title: 'Basic',
      code: '<Tooltip content="Copy to clipboard"><Button>Copy</Button></Tooltip>',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['overlay', 'hint', 'popover'],
  intent: {
    whenToUse: [
      'Labeling an icon-only control or clarifying a terse element on hover or focus',
      'Showing brief, supplementary text that is non-essential to completing the task',
      'Progressive disclosure of a short hint anchored to a trigger element',
    ],
    whenNotToUse: [
      'The content is interactive (links, buttons, inputs) — use Popover',
      'Richer non-interactive preview content is needed — use HoverCard',
      'The information is essential and must always be visible — render it inline instead',
    ],
    antiPatterns: [
      {
        bad: '<Tooltip content={<button>Undo</button>}><Icon /></Tooltip>',
        good: '<Popover><button>Undo</button></Popover>',
        why: 'Tooltips are hover/focus hints and cannot reliably hold focusable content; interactive content belongs in a Popover',
      },
    ],
    related: [
      {
        name: 'Popover',
        relationship: 'alternative',
        reason: 'Use when the floating content is interactive',
      },
      {
        name: 'HoverCard',
        relationship: 'alternative',
        reason: 'Use for richer non-interactive preview content',
      },
      {
        name: 'Button',
        relationship: 'pairs-with',
        reason: 'Commonly wraps an icon button to explain its action',
      },
    ],
    a11yRationale:
      'The floating element uses role="tooltip" and is linked to the trigger via aria-describedby only while visible; it shows on both hover and keyboard focus so it is reachable without a pointer.',
    content: {
      tone: 'Very short, plain phrase — a label or one-line hint',
      notes: 'No essential-only information; keep it to a few words and avoid full sentences',
    },
    flexibility: [
      {
        area: 'placement',
        level: 'strict',
        note: 'Limited to top | right | bottom | left, positioned via CSS anchor',
      },
      {
        area: 'delay',
        level: 'flexible',
        note: 'Consumer can tune the show delay (default 200ms)',
      },
    ],
  },
}
